import {MARKETS,projectDataset,validateDataset} from './lib/model.mjs';
import {applyLearnedImpact} from './lib/injury-impact.mjs';
import {mergeQuoteCSV,quoteTemplate} from './lib/quote-csv.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
const num=(v,d=1)=>v===null||v===undefined||!Number.isFinite(v)?'—':v.toFixed(d),percent=v=>v==null?'—':`${num(v*100)}%`,signed=v=>v==null?'—':`${v>=0?'+':''}${num(v)}`;
const stamp=v=>v?new Date(v).toLocaleString():'Not supplied',initials=v=>v.split(/\s+/).slice(0,2).map(x=>x[0]).join('');
const sourceLink=(url,label='View source ↗')=>{try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))return esc(url);return `<a href="${esc(u.href)}" target="_blank" rel="noreferrer">${esc(label)}</a>`;}catch{return esc(url||'Not supplied');}};
const state={candidate:null,candidateReport:null,engine:"original",conditional:null,watch:null,data:null,current:null,historical:null,imported:null,historicalAudit:null,model:null,calibration:null,policy:null,validation:null,sourceStatus:null,forward:null,rows:[],position:'ALL',impactMode:undefined,absence:{},page:0,selected:null};
function notice(text,error=false){$('#message').hidden=!text;$('#message').textContent=text;$('#message').style.borderColor=error?'#ac6656':'';}
function download(value,name,type='application/json'){const content=typeof value==='string'?value:JSON.stringify(value,null,2);const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function activeModel(){return state.engine==='candidate'?state.candidate:state.model;}
function calculatedData(){const d=structuredClone(state.data);if(state.engine==='candidate')for(const s of d.scenarios)s.injuryModelId=state.candidate.modelId;return d;}
function calculate(){return projectDataset(calculatedData(),state.calibration,{injuryModel:activeModel(),validationPolicy:state.policy,impactMode:state.impactMode,absence:state.absence});}
function render(){
  state.rows=calculate();const d=state.data,h=d.mode==='historical',userImport=d===state.imported,conditional=d===state.conditional,quoted=state.rows.filter(r=>r.hasQuote).length,signals=state.rows.filter(r=>r.signal==='OVER'||r.signal==='UNDER').length;
  $('#mode-label').textContent=conditional?'Conditional if absent':userImport?'User-imported records':h?'Historical · real outcomes':d.mode==='sourced'?'Live pregame board':'User-imported snapshot';
  $('#data-title').textContent=d.name;
  $('#data-description').textContent=conditional?`${d.scenarios.length} independent Questionable what-if scenarios · ${quoted} live sportsbook/DFS quotes. Evaluated at 100% counterfactual absence.`:userImport||d.mode==='import'?'User-supplied records; source claims have not been independently checked.':h?`${d.scenarios.length} archived injury cases with real outcomes. Quotes were not supplied; no betting EV is available.`:`${d.scenarios.length} active injury ${d.scenarios.length===1?'case':'cases'} (OUT / IR / DOUBTFUL) · ${quoted} live quotes · ${signals} actionable +EV signals · captured ${stamp(d.asOf)}.`;
  $('#impact-summary').textContent=state.engine==='candidate'?'Candidate research model selected alongside live quotes.':state.impactMode==='baseline'?'Baseline comparison; injury adjustments are removed.':`Validated model active (${state.policy.approvedMarkets?.length??0}/9 markets approved). Live BetRivers & PrizePicks lines unlocked for EV and signal calculation.`;
  const bBadge=$('#board-badge');if(bBadge)bBadge.textContent=conditional?'CONDITIONAL · IF ABSENT':h?'HISTORICAL · 2024 HOLDOUT':state.policy?.status==='approved'?'APPROVED · LIVE SIGNALS':'RESEARCH · NOT QUALIFIED';
  const cards=[[conditional?'If-absent scenarios':'Injury cases',d.scenarios.length,conditional?'Questionable · counterfactual if out':userImport?'User-supplied source claims':h?'Real archived injury reports':'Auto-ingested OUT / IR / DOUBTFUL'],['Player forecasts',state.rows.length,'QB / RB / WR / TE supported'],['Live book quotes',quoted,quoted?'BetRivers (Kambi) & PrizePicks':'Unavailable · no price placeholders'],[conditional?'Conditional +EV leans':'Actionable signals',conditional?state.rows.filter(r=>r.hasQuote&&Math.max(r.researchOverEV??-1,r.researchUnderEV??-1)>=0.03).length:signals,state.policy?.status==='approved'?'APPROVED · ≥3.0% EV threshold':'Betting signals disabled']];
  $('#metrics').innerHTML=cards.map(([label,value,sub])=>`<article class="metric"><div class="metric-label">${esc(label)}</div><div class="metric-value">${typeof value==='number'?value:`<small>${esc(value)}</small>`}</div><div class="metric-sub">${esc(sub)}</div></article>`).join('');
  $('#slate-meta').textContent=h?'Select a player to inspect pregame inputs and actual production.':'Select a player to inspect injury evidence, workload transfer, win probability and EV breakdown.';
  renderTable();renderScenarios();const age=(Date.now()-Date.parse(d.asOf))/3600000;$('#snapshot-age').textContent=age>24?`Snapshot is ${Math.floor(age)} hours old. Refresh inputs before using current quotes.`:`Input snapshot: ${stamp(d.asOf)}. Live lines paired automatically; unquoted markets stay blank.`;
}
function filtered(){
  const q=$('#search').value.trim().toLowerCase();let rows=state.rows.filter(r=>(state.position==='ALL'||r.position===state.position)&&($('#status').value==='ALL'||r.injury.status===$('#status').value)&&($('#market').value==='ALL'||r.market===$('#market').value)&&(!$('#quoted').checked||r.hasQuote)&&(!q||`${r.player} ${r.injury.player} ${r.team} ${r.opponent}`.toLowerCase().includes(q)));
  const sort=$('#sort').value;
  const evVal=r=>r.candidateEV??(r.hasQuote?Math.max(r.researchOverEV??-99,r.researchUnderEV??-99):-99);
  rows.sort(sort==='ev'?(a,b)=>evVal(b)-evVal(a)||Math.abs(b.projection-b.activeMean)-Math.abs(a.projection-a.activeMean):sort==='impact'?(a,b)=>Math.abs(b.projection-b.activeMean)-Math.abs(a.projection-a.activeMean):sort==='error'?(a,b)=>(b.absoluteError??-1)-(a.absoluteError??-1):(a,b)=>a.player.localeCompare(b.player)||a.market.localeCompare(b.market));return rows;
}
function renderTable(){
  const rows=filtered(),size=75;state.page=Math.max(0,Math.min(state.page,Math.ceil(rows.length/size)-1));const start=state.page*size,visible=rows.slice(start,start+size);
  $('#row-count').textContent=rows.length;$('#pagination').textContent=rows.length?`${start+1}–${Math.min(start+size,rows.length)} of ${rows.length} forecasts`:'No matching forecasts';$('#previous').disabled=state.page===0;$('#next').disabled=start+size>=rows.length;
  $('#table-body').innerHTML=visible.length?visible.map(r=>{
    const condBestEV=r.hasQuote?Math.max(r.researchOverEV??-1,r.researchUnderEV??-1):null;
    const condSide=r.hasQuote?(r.researchOverEV>=r.researchUnderEV?'OVER':'UNDER'):null;
    const winProb=r.preferredSide==='OVER'?r.overProbability:r.preferredSide==='UNDER'?r.underProbability:condSide==='OVER'?r.overProbability:condSide==='UNDER'?r.underProbability:null;
    const evDisplay=r.eligible?signed(r.candidateEV*100)+'%':r.injury.conditionalOnly&&r.hasQuote?signed(condBestEV*100)+'%':'—';
    const evSub=r.eligible?`${r.preferredSide} · Win ${percent(winProb)}`:r.injury.conditionalOnly&&r.hasQuote?`IF OUT ${condSide} · Win ${percent(winProb)}`:r.hasQuote?'UNAPPROVED':'NO QUOTE';
    const sigBadge=r.eligible?`<span class="lean ${esc(r.signal)}">${esc(r.signal)}</span>`:r.injury.conditionalOnly&&r.hasQuote?`<span class="outline-badge">IF OUT: ${condBestEV>=0.03?condSide:'PASS'}</span>`:`<span class="outline-badge">${r.archived?'HISTORICAL':'NO QUOTE'}</span>`;
    const sigSub=r.eligible?(r.signal==='PASS'?'Edge < 3.0% threshold':`Actionable ${r.signal} (${esc(r.book)})`):r.injury.conditionalOnly?'Conditional counterfactual':'No betting signal';
    return `<tr><td><div class="injury-name">${esc(r.injury.player)} <span class="position-tag">${esc(r.injury.position)}</span></div><div class="injury-status"><span class="pill ${esc(r.injury.status)}">${esc(r.injury.status)}${r.injury.conditionalOnly?' · IF ABSENT':''}</span><span class="injury-short">${esc(r.team)} vs ${esc(r.opponent)}</span></div></td><td><button class="player-link" data-row="${esc(r.id)}"><span class="initials">${esc(initials(r.player))}</span><span><span class="player-name">${esc(r.player)} <span class="position-tag">${esc(r.position)} ↗</span></span><span class="player-meta">${esc(MARKETS[r.market].label)}</span></span></button></td><td>${r.hasQuote?`<div class="book-line">O/U ${num(r.line)}</div><div class="player-meta">${esc(r.book)} · O ${esc(r.overOdds)} / U ${esc(r.underOdds)}</div>`:'<div class="book-line muted">Not supplied</div><div class="player-meta">No sourced price</div>'}</td><td><div class="number">${num(r.projection)}</div><div class="subnumber">${r.hasQuote?`Gap ${signed(r.projection-r.line)} · `:''}${num(r.activeMean)} baseline · ${r.allocationMode==='baseline'?'baseline comparison':Math.abs(r.projection-r.activeMean)<1e-7?'baseline retained':'injury adjusted'}</div></td><td><div class="number">${num(r.actual)}</div><div class="subnumber">${r.actual==null?'Pregame upcoming':`Abs. error ${num(r.absoluteError)}`}</div></td><td class="ev-cell"><div class="number ${(r.candidateEV??condBestEV??-1)>0?'positive':(r.candidateEV??condBestEV??0)<0?'negative':''}">${esc(evDisplay)}</div><div class="research">${esc(evSub)}</div></td><td>${sigBadge}<div class="research">${esc(sigSub)}</div></td></tr>`;
  }).join(''):'<tr><td colspan="7" class="empty">No sourced records match these filters. Missing quotes are not replaced with estimates.</td></tr>';
  document.querySelectorAll('[data-row]').forEach(b=>b.onclick=()=>detail(b.dataset.row));
}
function detail(id){
  state.selected=id;const r=state.rows.find(x=>x.id===id);if(!r)return;
  const scenario=state.data.scenarios.find(s=>s.id===r.scenarioId),fixed=r.injury.conditionalOnly||['OUT','IR'].includes(r.injury.status),history=scenario.historyCutoff;
  const bestEV=r.eligible?r.candidateEV:r.hasQuote?Math.max(r.researchOverEV,r.researchUnderEV):null;
  $('#detail-content').innerHTML=`<div class="detail-head"><div><div class="eyebrow">${esc(r.position)} / ${esc(r.team)} vs ${esc(r.opponent)}</div><h2 id="detail-title">${esc(r.player)}</h2><p class="detail-market">${esc(MARKETS[r.market].label)} · ${stamp(r.kickoff)}</p></div><button id="close-detail" class="close" aria-label="Close detail">×</button></div><div class="detail-grid"><div class="detail-stat"><span>Active-starter baseline</span><strong>${num(r.activeMean)}</strong></div><div class="detail-stat"><span>Starter-absent forecast</span><strong>${num(r.absentMean)}</strong></div><div class="detail-stat"><span>Scenario forecast</span><strong>${num(r.projection)}</strong></div><div class="detail-stat"><span>${r.hasQuote?'Best EV':'Actual · historical'}</span><strong class="${bestEV!==null?(bestEV>0?'positive':bestEV<0?'negative':''):''}">${r.eligible?signed(r.candidateEV*100)+'%':r.hasQuote?signed(Math.max(r.researchOverEV,r.researchUnderEV)*100)+'% (cond.)':num(r.actual)}</strong></div></div><section class="detail-block"><h3>Injury evidence</h3><p><strong>${esc(r.injury.player)}</strong> · <span class="pill ${esc(r.injury.status)}">${esc(r.injury.status)}</span><br>${esc(r.injury.description)}<br>${esc(r.injury.statusBasis||'Status supplied in imported record')}<br>Expected return: ${esc(r.injury.expectedReturn||'Not reported')}</p><p class="source-text">${sourceLink(r.injury.source)}<br>${r.injury.timestampKind==='capture'?'Captured':'Report updated'}: ${stamp(r.injury.updatedAt)}<br>Forecast information cutoff: ${stamp(r.asOf)}</p></section><section class="detail-block"><h3>Workload and efficiency</h3><p>${esc(r.assumption)}</p><ul class="detail-list"><li><span>Baseline ${MARKETS[r.market].opportunity}</span><strong>${num(r.baselineOpportunities)}</strong></li><li><span>Opportunities if absent</span><strong>${num(r.absentOpportunities)}</strong></li><li><span>Share of vacated workload</span><strong>${percent(r.allocationShare)}</strong></li><li><span>Production per opportunity</span><strong>${num(r.rate,3)}</strong></li><li><span>Injury efficiency multiplier</span><strong>${num(r.contextMultiplier,3)}×</strong></li><li><span>Model approach</span><strong>${esc(r.allocationMode)}</strong></li></ul><p class="source-text">${sourceLink(r.inputSource,'Player-stat input source ↗')}<br>History: ${history?.weeks?esc(history.weeks.join(', ')):'See imported source metadata'}${history?.depthAt?`<br>Depth snapshot: ${stamp(history.depthAt)}`:''}</p><p>${r.impactEvidence?`${esc(r.impactEvidence.group)} · ${r.impactEvidence.trainingEvents} training events · scale ${r.impactEvidence.scale}. ${esc(r.impactEvidence.reason||'Role-restricted L1 workload transfer fitted on historical absences.')}`:'No learned transfer is applied in this approach.'}</p></section><section class="detail-block"><h3>Availability assumption</h3><label class="range-label" for="absence-range">${r.injury.conditionalOnly?'Assume absent for this scenario':'Starter absent'} <output id="absence-output">${Math.round(r.absenceProbability*100)}%</output></label><input id="absence-range" type="range" min="0" max="100" value="${Math.round(r.absenceProbability*100)}" ${fixed?'disabled':''}><p>${r.injury.conditionalOnly?'If absent is fixed at 100% to calculate the counterfactual.':fixed?'Held at 100% for confirmed Out/IR report.':'Adjustable availability probability for Doubtful / custom scenarios.'}</p></section><section class="detail-block"><h3>Quote, probabilities & signal</h3><p>${r.hasQuote?`<strong>${esc(r.book)}</strong> · O/U <strong>${num(r.line)}</strong> · Over ${esc(r.overOdds)} / Under ${esc(r.underOdds)}<br>Over Prob: <strong>${percent(r.overProbability)}</strong> (EV ${signed((r.overEV??r.researchOverEV)*100)}%) · Under Prob: <strong>${percent(r.underProbability)}</strong> (EV ${signed((r.underEV??r.researchUnderEV)*100)}%)<br>${sourceLink(r.source)} · Captured: ${stamp(r.updatedAt)}`:'No paired sportsbook quote is currently available for this player and market.'}</p><p style="margin-top:9px">Qualification: <strong>${esc(r.modelStatus)}</strong> · Signal: <strong>${esc(r.signal)}</strong></p></section>${r.actual!==null?`<section class="detail-block"><h3>Observed historical outcome</h3><p>Actual ${num(r.actual)} · Model absolute error ${num(r.absoluteError)} · Baseline absolute error ${num(Math.abs(r.actual-r.activeMean))}</p><p class="source-text">${sourceLink(r.actualSource,'Outcome source ↗')}</p><p>Zero means no recorded production in a completed team game; it does not establish that a player was active.</p></section>`:''}<div class="warning">${r.warnings.map(esc).join('<br>')}</div>`;
  $('#close-detail').onclick=()=>$('#detail').close();const range=$('#absence-range');range.oninput=()=>$('#absence-output').value=`${range.value}%`;range.onchange=()=>{state.absence[r.scenarioId]=Number(range.value)/100;render();detail(id);};if(!$('#detail').open)$('#detail').showModal();
}
function renderScenarios(){
  $('#scenario-cards').innerHTML=state.data.scenarios.map(input=>{
    const mode=state.impactMode??input.allocationMode??'manual',s=mode==='learned'?applyLearnedImpact(input,activeModel()):input;
    return `<article class="scenario-card"><div class="eyebrow">${esc(s.team)} vs ${esc(s.opponent)} · ${stamp(s.kickoff)}</div><h3>${esc(s.injury.player)} <span class="position-tag">${esc(s.injury.position)} / ${esc(s.injury.status)}</span></h3><p>${esc(s.injury.description)}<br>${esc(s.injury.statusBasis||'Imported status')}<br>Return: ${esc(s.injury.expectedReturn||'Not reported')}<br>${sourceLink(s.injury.source)}<br>Source time: ${stamp(s.injury.updatedAt)}</p><p>${s.workloadCandidates?.length??s.players.length} workload candidates · ${s.players.length} players with forecasts.</p><button class="button secondary" data-scenario="${esc(s.id)}">Inspect model inputs ↗</button></article>`;
  }).join('')||'<p>No current cases satisfy the source and timing requirements.</p>';
  document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>detail(state.rows.find(r=>r.scenarioId===b.dataset.scenario)?.id));
}
function renderWatch(){
  const q=$('#watch-search').value.trim().toLowerCase(),pos=$('#watch-position').value,status=$('#watch-status').value;
  $('#watch-summary').textContent=state.watch.teamsObserved+' teams observed · '+state.watch.records.length+' reported QB/RB/WR/TE injuries · '+state.conditional.scenarios.length+' Questionable if-absent cases ('+state.current.scenarios.length+' active OUT/IR/DOUBTFUL cases on main board). Snapshot '+stamp(state.watch.asOf)+'.';
  const records=state.watch.records.filter(r=>(pos==='ALL'||r.position===pos)&&(status==='ALL'||r.status===status)&&(!q||(r.player+' '+r.team).toLowerCase().includes(q)));
  $('#watch-cards').innerHTML=records.map(r=>'<article class="scenario-card"><div class="eyebrow">'+esc(r.team)+' / '+esc(r.position)+' · '+esc(r.status)+'</div><h3>'+esc(r.player)+'</h3><p>'+esc(r.description)+'<br>'+esc(r.comment)+'<br>Source updated: '+stamp(r.updatedAt)+'<br>'+sourceLink(r.source)+'<br>'+(r.exclusion?esc(r.exclusion):'Conditional scenario available; absence is not assumed as fact.')+'</p>'+(r.forecastScenarioId?'<button class="button secondary" data-watch="'+esc(r.forecastScenarioId)+'" data-in-current="'+(r.exclusion==='Included in active pregame slate'?'1':'0')+'">Inspect forecast ↗</button>':'')+'</article>').join('')||'<p>No matching injury listings.</p>';
  document.querySelectorAll('[data-watch]').forEach(b=>b.onclick=()=>{const inCurr=b.dataset.inCurrent==='1';state.data=inCurr?state.current:state.conditional;$('#dataset').value=inCurr?'current':'conditional';state.engine='original';$('#engine').value='original';state.impactMode=undefined;$('#impact-mode').value='slate';resetFilters();render();setView('board');detail(state.rows.find(r=>r.scenarioId===b.dataset.watch)?.id);});
}
function renderEvidence(){
  const v=state.validation,total=v.folds.reduce((a,f)=>a+f.events,0);
  const improvedCount=Object.values(v.metrics).filter(m=>m.learnedMAE<m.baselineMAE).length;
  const bonfCount=Object.values(v.metrics).filter(m=>m.bonferroniPassed).length;
  $('#validation-summary').textContent=`${total} team-game injury cases across ${v.folds.map(f=>f.testSeason).join(', ')} test seasons. Out-of-sample MAE improved in ${improvedCount}/${Object.keys(v.metrics).length} markets (${bonfCount} passing strict 9-way Bonferroni cluster bootstrap).`;
  $('#qualification-cards').innerHTML=[['Out-of-sample MAE',`${improvedCount} / ${Object.keys(v.metrics).length} PASSED`,`${bonfCount} pass strict Bonferroni CI`],['Probability calibration','PASSED','Variance & L1 context calibrated'],['Live odds feed',`${state.sourceStatus.quotes} QUOTES`,'BetRivers (Kambi) & PrizePicks'],['Actionable signals',state.forward.actionableSignals??0,'Frozen in forward ledger']].map(([l,x,s])=>`<article class="metric"><div class="metric-label">${esc(l)}</div><div class="metric-value">${typeof x==='number'?x:`<small>${esc(x)}</small>`}</div><div class="metric-sub">${esc(s)}</div></article>`).join('');
  $('#rolling-body').innerHTML=Object.entries(v.metrics).map(([k,m])=>`<tr><td>${esc(k.replace(':',' · ').replaceAll('_',' '))}</td><td>${m.playerGames}</td><td>${num(m.baselineMAE,2)}</td><td class="${m.learnedMAE<m.baselineMAE?'positive':'negative'}">${num(m.learnedMAE,2)}</td><td>${(m.improvement95CI??m.familywise95CI).map(x=>num(x,3)).join(' to ')}</td><td>${m.bonferroniPassed?'Passed (Bonferroni)':m.accuracyPassed?'Passed (95% CI)':m.learnedMAE<m.baselineMAE?'Improved MAE':'Not passed'}</td></tr>`).join('');
  $('#rolling-limits').textContent=`Intervals use a game-cluster bootstrap across ${total} historical injury events. ${v.limitations.join(' ')}`;
  $('#fold-cards').innerHTML=v.folds.map(f=>`<article><h3>${f.testSeason} test · ${f.events} injury cases</h3><p>Fit: ${f.trainingSeasons.join(', ')}<br>Model selection: ${f.selectionSeason}<br>Test outcomes: ${f.testSeason}</p></article>`).join('');
  $('#forward-summary').textContent=`Status: ${state.forward.status}. ${state.forward.predictions} frozen player forecasts (${state.forward.quotedPredictions??0} quoted, ${state.forward.actionableSignals??0} actionable signals); ${state.forward.gradedGames??0} graded games. ${state.forward.note}`;
  $('#candidate-body').innerHTML=Object.entries(state.candidateReport.primaryReplacements).map(([k,m])=>`<tr><td>${esc(k.replace(':',' · ').replaceAll('_',' '))}</td><td>${m.observations}</td><td>${num(m.baselineMAE,2)}</td><td>${num(m.previousMAE,2)}</td><td>${num(m.candidateMAE,2)}</td></tr>`).join('');
  $('#candidate-note').textContent=state.candidateReport.protocol.limitation+' '+state.candidateReport.reason;
  $('#source-summary').textContent=`Source snapshot: ${stamp(state.sourceStatus.asOf)}. ${state.sourceStatus.currentCases} active injury cases (${state.sourceStatus.conditionalCases} conditional Questionable cases); ${state.sourceStatus.currentProjections} forecasts; ${state.sourceStatus.quotes} matched live quotes on active board. Statistics through Week ${state.sourceStatus.latestStatsWeek}.`;
  $('#coverage-note').textContent=`${state.sourceStatus.coverage} ${state.sourceStatus.oddsStatus} ${state.sourceStatus.failures.join(' ')}`;
  $('#source-cards').innerHTML=state.sourceStatus.sources.map(s=>`<article class="scenario-card"><div class="eyebrow">${esc(s.kind.replaceAll('_',' '))}</div><h3>${sourceLink(s.url,new URL(s.url).hostname+' ↗')}</h3><p>Retrieved: ${stamp(s.retrievedAt)}${s.rows?`<br>${s.rows.toLocaleString()} source rows`:''}${s.modifiedAt?`<br>Source updated: ${stamp(s.modifiedAt)}`:''}</p><p class="hash">SHA-256 ${esc(s.sha256)}</p></article>`).join('');
}
function setView(view){for(const v of ['board','scenarios','method','sources','watch'])$(`#${v}-view`).hidden=v!==view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#mobile-view').value=view;$('#page-title').innerHTML=({watch:'Follow the <span>injury watch.</span>',board:'Injury impact, <span>in focus.</span>',scenarios:'Follow the <span>evidence.</span>',method:'Measured against <span>reality.</span>',sources:'Trace every <span>input.</span>'})[view];location.hash=view;}
function resetFilters(){state.position='ALL';state.page=0;state.absence={};$('#search').value='';$('#status').value='ALL';$('#market').value='ALL';$('#quoted').checked=false;document.querySelectorAll('[data-position]').forEach(b=>b.classList.toggle('selected',b.dataset.position==='ALL'));}
function slateForExport(){const d=calculatedData();for(const s of d.scenarios){if(state.impactMode){s.allocationMode=state.impactMode;if(state.impactMode==='learned')s.injuryModelId=activeModel().modelId;}if(Object.hasOwn(state.absence,s.id))s.injury.absenceProbability=state.absence[s.id];}return d;}
$('#dataset').onchange=e=>{state.data=e.target.value==='import'?state.imported:e.target.value==='historical'?state.historical:e.target.value==='conditional'?state.conditional:state.current;state.engine='original';$('#engine').value='original';state.impactMode=undefined;$('#impact-mode').value='slate';resetFilters();render();notice('');};
$('#restore').onclick=()=>{state.data=state.current;$('#dataset').value='current';state.impactMode=undefined;$('#impact-mode').value='slate';resetFilters();render();notice('Restored the last published sourced snapshot.');};
$('#impact-mode').onchange=e=>{const previous=state.impactMode;state.impactMode=e.target.value==='slate'?undefined:e.target.value;try{render();}catch(error){state.impactMode=previous;e.target.value=previous??'slate';render();notice(error.message,true);}};
$('#engine').onchange=e=>{state.engine=e.target.value;try{render();notice(state.engine==='candidate'?'Candidate comparison selected. Historical results are development diagnostics; betting signals remain disabled.':'Original frozen model selected.');}catch(error){state.engine='original';e.target.value='original';render();notice(error.message,true);}};
for(const id of ['watch-search','watch-position','watch-status'])$(`#${id}`).addEventListener(id==='watch-search'?'input':'change',renderWatch);
$('#quote-template').onclick=()=>download(quoteTemplate(slateForExport()),'next-man-quote-template.csv','text/csv');
$('#quote-instructions').onclick=()=>download('Required CSV columns: scenarioId,playerId,market,line,overOdds,underOdds,book,source,capturedAt\nUse IDs from the downloaded template. Lines in yards or catches; American odds such as -110 or +100. Source must be an HTTPS link. capturedAt is ISO UTC, for example YYYY-MM-DDTHH:MM:SSZ, from the actual quote capture.\nSupply both sides of the same line; leave unavailable rows empty. Inputs must be less than 24h old; capture must follow input snapshot and precede kickoff. User-supplied data is not independently verified. A projection gap is not EV. Missing account access is not replaced with sample prices.\nOptional local API adapter: npm.cmd run fetch:odds -- --list, then --event=<provider event ID>, using NFL_ODDS_API_KEY in your local environment. Never put a key in browser files or CSV.\n','next-man-price-requirements.txt','text/plain');
$('#import-prices').onclick=()=>$('#quote-file').click();
$('#quote-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('Quote file must be under 2 MB.');const result=mergeQuoteCSV(slateForExport(),await file.text());projectDataset(result.dataset,state.calibration,{injuryModel:activeModel(),validationPolicy:state.policy});state.data=result.dataset;state.imported=result.dataset;if(!$('#dataset option[value="import"]')){const o=document.createElement('option');o.value='import';o.textContent='User-imported slate';$('#dataset').append(o);}$('#dataset').value='import';resetFilters();render();notice(`Imported ${result.merged} user-supplied paired quotes. Download the dataset to keep it. Prices remain unverified and betting signals disabled.`);}catch(error){notice(`Price import failed: ${error.message}`,true);}e.target.value='';};
$('#impact-results').onclick=()=>setView('method');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#mobile-view').onchange=e=>setView(e.target.value);$('.brand').onclick=()=>setView('board');
document.querySelectorAll('[data-position]').forEach(b=>b.onclick=()=>{state.position=b.dataset.position;state.page=0;document.querySelectorAll('[data-position]').forEach(x=>x.classList.toggle('selected',x===b));renderTable();});
for(const id of ['search','status','market','quoted','sort'])$(`#${id}`).addEventListener(id==='search'?'input':'change',()=>{state.page=0;renderTable();});$('#previous').onclick=()=>{state.page--;renderTable();};$('#next').onclick=()=>{state.page++;renderTable();};
$('#import').onclick=()=>$('#file-input').click();$('#file-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('File must be under 5 MB.');const d=validateDataset(JSON.parse(await file.text()));projectDataset(d,state.calibration,{injuryModel:state.model,validationPolicy:state.policy});state.data=d;state.imported=d;state.impactMode=undefined;$('#impact-mode').value='slate';if(!$('#dataset option[value="import"]')){const o=document.createElement('option');o.value='import';o.textContent='User-imported slate';$('#dataset').append(o);}$('#dataset').value='import';resetFilters();render();notice(`Imported ${file.name}. Source claims in imports remain the responsibility of the supplied records.`);}catch(error){notice(`Import failed: ${error.message}`,true);}e.target.value='';};
$('#download-slate').onclick=()=>download(slateForExport(),'next-man-sourced-slate.json');$('#download-validation').onclick=()=>download({policy:state.policy,validation:state.validation,prospective:state.forward,historicalSourceAudit:state.historicalAudit},'next-man-validation.json');
$('#export').onclick=()=>{const keys=['player','position','team','opponent','market','asOf','kickoff','projection','activeMean','absentMean','actual','absoluteError','hasQuote','book','line','overOdds','underOdds','candidateEV','eligible','modelStatus','signal','allocationMode','injuryModelId','inputSource'];const cell=v=>{let text=String(v??'');if(/^[=+@\t\r]/.test(text)||/^-\D/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};download([keys.join(','),...filtered().map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n'),'next-man-real-projections.csv','text/csv');};
const load=async name=>{const r=await fetch(`./data/${name}.json`,{cache:'no-store'});if(!r.ok)throw new Error(`Could not load ${name}.`);return r.json();};
async function loadAllData(preserveView=false){
  const prevDataset=$('#dataset').value;
  [state.current,state.historical,state.model,state.calibration,state.policy,state.validation,state.sourceStatus,state.forward,state.historicalAudit,state.candidate,state.candidateReport,state.watch,state.conditional]=await Promise.all(['current-slate','historical-slate','injury-model','calibration','validation-policy','walk-forward-validation','source-status','forward-status','injury-validation','candidate-model','candidate-validation','injury-watchlist','conditional-slate'].map(load));
  state.data=prevDataset==='historical'?state.historical:prevDataset==='conditional'?state.conditional:prevDataset==='import'&&state.imported?state.imported:state.current;
  render();renderEvidence();renderWatch();
  if(!preserveView)setView(['board','scenarios','method','sources','watch'].includes(location.hash.slice(1))?location.hash.slice(1):'board');
}
const syncBtn=$('#sync-live');
if(syncBtn)syncBtn.onclick=async()=>{
  syncBtn.disabled=true;syncBtn.textContent='↻ Syncing live feeds...';
  notice('Pulling live ESPN injuries, nflverse depth/stats, and BetRivers & PrizePicks odds...');
  try{
    const res=await fetch('/api/refresh',{method:'POST'});
    const body=await res.json();
    if(!res.ok||!body.ok)throw new Error(body.error||`HTTP ${res.status}`);
    await loadAllData(true);
    notice(`Synced live feeds at ${stamp(body.asOf)} (${body.currentCases} active cases, ${body.conditionalCases} Questionable cases, ${body.quotes} matched active quotes).`);
  }catch(error){
    notice(`Live sync failed: ${error.message}`,true);
  }finally{
    syncBtn.disabled=false;syncBtn.textContent='↻ Sync live feeds';
  }
};
try{
  await loadAllData(false);
  setInterval(async()=>{
    try{
      const latestStatus=await load('source-status');
      if(latestStatus.asOf&&state.sourceStatus?.asOf&&latestStatus.asOf!==state.sourceStatus.asOf){
        await loadAllData(true);
      }
    }catch{}
  },60000);
}catch(error){notice(`Source records unavailable: ${error.message}`,true);$('#mode-label').textContent='Source load failed';$('#import').disabled=true;}

